WITH building AS (
  SELECT geometry FROM lisbon_buildings WHERE names.primary = 'Torre VTS de Algés'
)
SELECT p.id, p.names.primary AS name, p.basic_category
FROM lisbon_places p, building b
WHERE ST_Within(p.geometry, b.geometry);

WITH schools AS (
  SELECT geometry FROM lisbon_buildings WHERE class = 'school'
)
SELECT DISTINCT b.id, b.names.primary AS building_name, b.class
FROM lisbon_buildings b, schools s
WHERE ST_Touches(b.geometry, s.geometry);

SELECT p.id, p.names.primary AS name, p.basic_category
FROM lisbon_places p
WHERE NOT EXISTS (
  SELECT 1 FROM lisbon_buildings b
  WHERE ST_Within(p.geometry, b.geometry)
);

SELECT DISTINCT b.id, b.names.primary AS building_name, b.subtype
FROM lisbon_buildings b
WHERE EXISTS (
  SELECT 1 FROM lisbon_places p
  WHERE ST_Contains(b.geometry, p.geometry)
);
